use vstd::prelude::*;

verus! {

    // Given a non‐empty vector of i32, returns the smallest element.
    // Ensures:
    //   1) The result is ≤ every element in the vector.
    //   2) The result actually appears in the vector.
    fn smallest_num(nums: &Vec<i32>) -> (min: i32)
        requires
            nums.len() > 0,
        ensures
            // min is ≤ every element
            forall |i: usize| i < nums.len() ==> min <= nums[i],
            // min appears somewhere in the vector
            exists |i: usize| i < nums.len() && nums[i] == min,
    {
        // We scan from left to right, remembering the index of the current minimum.
        let mut idx: usize = 1;
        let mut min_idx: usize = 0;
        let mut min: i32 = nums[0];

        while idx < nums.len()
            invariant
                // We have scanned exactly the prefix [0..idx)
                idx <= nums.len(),
                // min_idx points into that prefix
                min_idx < idx,
                // min equals nums[min_idx]
                min == nums[min_idx],
                // And min ≤ every element seen so far
                forall |j: usize| j < idx ==> min <= nums[j],
            decreases
                nums.len() - idx,
        {
            let x = nums[idx];
            if x < min {
                min = x;
                min_idx = idx;
            }
            idx = idx + 1;
        }

        // At exit idx == nums.len(), so by the invariants we have:
        //   min ≤ every element in [0..nums.len())
        // and
        //   nums[min_idx] == min with min_idx < nums.len().
        min
    }

}

